import { z } from "zod";
const zCloseWindowProps = z
    .object({
    message: z.string().optional(),
})
    .partial();
export function CloseWindow(define) {
    return define("CloseWindow")
        .props(zCloseWindowProps)
        .render((props) => ({
        id: props.id,
        message: props.message,
    }));
}
